DO $$ DECLARE r record; v text; BEGIN FOR r IN SELECT p.oid,p.proname,pg_get_function_identity_arguments(p.oid) args FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('customer_portal_overview','customer_portal_task_orders','customer_submit_task_order') LOOP v:=pg_get_functiondef(r.oid); v:=replace(v,'pl.project_id = t.project_id','pl.project_id = t.project_id AND COALESCE(pl.customer_id, (SELECT customer_id FROM public.projects WHERE id=pl.project_id)) = t.customer_id'); v:=replace(v,'id = p_location AND project_id = t.project_id','id = p_location AND project_id = t.project_id AND COALESCE(customer_id, (SELECT customer_id FROM public.projects WHERE id=t.project_id)) = t.customer_id'); EXECUTE v; EXECUTE format('REVOKE ALL ON FUNCTION public.%I(%s) FROM PUBLIC,anon,authenticated',r.proname,r.args); EXECUTE format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO anon,authenticated,service_role',r.proname,r.args); END LOOP; END $$;